84|   const ctx = canvas.getContext("2d");
85|   const clearBtn = document.getElementById("clearBtn");
86|   const tallyPlate = document.getElementById("tallyPlate");
87| 
88|   let dpr = Math.max(1, window.devicePixelRatio || 1);
89|   let W = window.innerWidth, H = window.innerHeight;
90| 
91|   function resize() {
92|     W = window.innerWidth;
93|     H = window.innerHeight;
94|     dpr = Math.max(1, window.devicePixelRatio || 1);
95|     canvas.width = Math.floor(W * dpr);
96|     canvas.height = Math.floor(H * dpr);
97|     canvas.style.width = W + "px";
98|     canvas.style.height = H + "px";
99|     ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
100|   }
101|   window.addEventListener("resize", resize);
102|   resize();
103| 
104|   const PALETTE = {
105|     bg: "#f4ecd8",
106|     layer: "#e07a5f",
107|     accent: "#3d405b",
108|     highlight: "#81b29a"
109|   };
110| 
111|   const bubbleColors = [PALETTE.layer, PALETTE.highlight, PALETTE.accent];
112| 
113|   // seeded jitter helper
114|   function seededRand(seed) {
115|     let s = seed;
116|     return function () {
117|       s = (s * 9301 + 49297) % 233280;
118|       return s / 233280;
119|     };
120|   }
121| 
122|   let paused = false;
123|   let running = false;
124|   let tally = 0;
125|   const bubbles = [];
126|   const pops = []; // pop animations
127| 
128|   let bubbleIdCounter = 1;
129| 
130|   function spawnBubble() {
131|     const r = 26 + Math.random() * 30;
132|     const x = r + Math.random() * (W - 2 * r);
133|     const y = H + r + Math.random() * 100;
134|     const speed = 0.4 + Math.random() * 0.6;
135|     const colorIdx = Math.floor(Math.random() * bubbleColors.length);
136|     const rnd = seededRand(Math.floor(Math.random() * 100000));
137|     const jitter = [];
138|     for (let i = 0; i < 10; i++) {
139|       jitter.push((rnd() - 0.5) * 3);
140|     }
141|     bubbles.push({
142|       id: bubbleIdCounter++,
143|       x, y, r,
144|       speed,
145|       color: bubbleColors[colorIdx],
146|       wobblePhase: Math.random() * Math.PI * 2,
147|       jitter
148|     });
149|   }
150| 
151|   function maintainBubbles() {
152|     const target = Math.min(10, 4 + Math.floor(tally / 5));
153|     while (bubbles.length < target) {
154|       spawnBubble();
155|     }
156|   }
157| 
158|   let lastSpawnTime = 0;
159| 
160|   function settle(dtSeconds) {
161|     for (let i = bubbles.length - 1; i >= 0; i--) {
162|       const b = bubbles[i];
163|       b.y -= b.speed;
164|       b.wobblePhase += 0.02;
165|       if (b.y < -b.r - 50) {
166|         bubbles.splice(i, 1);
167|       }
168|     }
169|     lastSpawnTime += dtSeconds;
170|     if (lastSpawnTime > 0.5) {
171|       lastSpawnTime = 0;
172|       maintainBubbles();
173|     }
174|     for (let i = pops.length - 1; i >= 0; i--) {
175|       pops[i].life -= dtSeconds;
176|       if (pops[i].life <= 0) pops.splice(i, 1);
177|     }
178|   }
179| 
180|   function popBubbleAt(index) {
181|     const b = bubbles[index];
182|     pops.push({ x: b.x, y: b.y, r: b.r, color: b.color, life: 0.35, maxLife: 0.35 });
183|     bubbles.splice(index, 1);
184|     tally += 1;
185|     tallyPlate.textContent = "Pops: " + tally;
186|     CARTRIDGE.send("score", { value: tally });
187|   }
188| 
189|   function hitTest(px, py) {
190|     for (let i = bubbles.length - 1; i >= 0; i--) {
191|       const b = bubbles[i];
192|       const dx = px - b.x, dy = py - b.y;
193|       if (dx * dx + dy * dy <= b.r * b.r) {
194|         return i;
195|       }
196|     }
197|     return -1;
198|   }
199| 
200|   function drawRoundedBubble(b) {
201|     const wob = Math.sin(b.wobblePhase) * 2;
202|     ctx.save();
203|     ctx.shadowColor = "rgba(61,64,91,0.35)";
204|     ctx.shadowBlur = 6;
205|     ctx.shadowOffsetY = 3;
206|     ctx.beginPath();
207|     const points = 10;
208|     for (let i = 0; i < points; i++) {
209|       const angle = (i / points) * Math.PI * 2;
210|       const jitterAmt = b.jitter[i];
211|       const rr = b.r + jitterAmt;
212|       const px = b.x + Math.cos(angle) * rr + wob * 0.2;
213|       const py = b.y + Math.sin(angle) * rr;
214|       if (i === 0) ctx.moveTo(px, py);
215|       else ctx.lineTo(px, py);
216|     }
217|     ctx.closePath();
218|     ctx.fillStyle = b.color;
219|     ctx.fill();
220|     ctx.restore();
221| 
222|     // inner highlight card
223|     ctx.save();
224|     ctx.globalAlpha = 0.35;
225|     ctx.beginPath();
226|     ctx.ellipse(b.x - b.r * 0.3, b.y - b.r * 0.35, b.r * 0.28, b.r * 0.18, -0.5, 0, Math.PI * 2);
227|     ctx.fillStyle = "#f4ecd8";
228|     ctx.fill();
229|     ctx.restore();
230|   }
231| 
232|   function drawPop(p) {
233|     const t = 1 - p.life / p.maxLife;
234|     const rad = p.r * (1 + t * 0.8);
235|     ctx.save();
236|     ctx.globalAlpha = 1 - t;
237|     ctx.beginPath();
238|     const points = 8;
239|     for (let i = 0; i < points; i++) {
240|       const angle = (i / points) * Math.PI * 2;
241|       const rr = rad * (0.6 + 0.4 * Math.sin(i * 3 + t * 6));
242|       const px = p.x + Math.cos(angle) * rr;
243|       const py = p.y + Math.sin(angle) * rr;
244|       if (i === 0) ctx.moveTo(px, py);
245|       else ctx.lineTo(px, py);
246|     }
247|     ctx.closePath();
248|     ctx.fillStyle = p.color;
249|     ctx.fill();
250|     ctx.restore();
251|   }
252| 
253|   let hintPhase = 0;
254| 
255|   function draw() {
256|     ctx.clearRect(0, 0, W, H);
257|     ctx.fillStyle = PALETTE.bg;
258|     ctx.fillRect(0, 0, W, H);
259| 
260|     // subtle layered background strips
261|     ctx.save();
262|     ctx.globalAlpha = 0.5;
263|     ctx.fillStyle = PALETTE.highlight;
264|     ctx.beginPath();
265|     ctx.roundRect ? ctx.roundRect(0, H - 40, W, 40, 10) : ctx.rect(0, H - 40, W, 40);
266|     ctx.fill();
267|     ctx.restore();
268| 
269|     for (const b of bubbles) drawRoundedBubble(b);
270|     for (const p of pops) drawPop(p);
271| 
272|     if (!running) {
273|       hintPhase += 0.05;
274|       const alpha = 0.6 + Math.sin(hintPhase) * 0.4;
275|       ctx.save();
276|       ctx.globalAlpha = Math.max(0.2, alpha);
277|       ctx.fillStyle = PALETTE.accent;
278|       ctx.font = "bold 28px sans-serif";
279|       ctx.textAlign = "center";
280|       ctx.textBaseline = "middle";
281|       ctx.fillText("Tap to begin", W / 2, H / 2);
282|       ctx.restore();
283|     }
284|   }
285| 
286|   let lastFrameTime = performance.now();
287| 
288|   function frame() {
289|     const now = performance.now();
290|     const dt = Math.min(0.05, (now - lastFrameTime) / 1000);
291|     lastFrameTime = now;
292|     if (!paused && running) {
293|       settle(dt);
294|     }
295|     draw();
296|     requestAnimationFrame(frame);
297|   }
298| 
299|   // Single clear-the-table function: used by the visible Clear button,
300|   // and by the host "reset" command. Both paths call this same function.
301|   function backToTitle() {
302|     bubbles.length = 0;
303|     pops.length = 0;
304|     tally = 0;
305|     running = false;
306|     tallyPlate.textContent = "Pops: 0";
307|     CARTRIDGE.send("score", { value: 0 });
308|     draw();
309|   }
310| 
311|   clearBtn.addEventListener("click", backToTitle);
312| 
313|   canvas.style.touchAction = "none";
314|   canvas.addEventListener("pointerdown", (event) => {
315|     event.preventDefault();
316|     if (paused) return;
317|     const rect = canvas.getBoundingClientRect();
318|     const px = event.clientX - rect.left;
319|     const py = event.clientY - rect.top;
320|     if (!running) {
321|       running = true;
322|       CARTRIDGE.send("start");
323|       maintainBubbles();
324|       return;
325|     }
326|     const idx = hitTest(px, py);
327|     if (idx >= 0) {
328|       popBubbleAt(idx);
329|     }
330|   });
331| 
332|   window.addEventListener("message", (event) => {
333|     const data = event.data;
334|     if (!data || data.source !== "cartridge-host") return;
335|     if (data.type === "pause") paused = true;
336|     if (data.type === "resume") paused = false;
337|     if (data.type === "reset") backToTitle();
338|   });
339| 
340|   // initial draw + boot
341|   draw();
342|   CARTRIDGE.send("boot", { title: "Pop the Bubbles", gameType: "toy-box", lang: "en" });
343| 
344|   requestAnimationFrame(frame);
345| })();
346| </script>
347| </body>
348| </html>
